function dividerMenu(existing=null){const anchor=(fly||root)?.getBoundingClientRect();const menu=popup('<div class="rt-label">구분선 종류</div>'+[['solid','실선'],['dashed','파선'],['dotted','점선'],['double','이중선'],['thick','굵은 선']].map(([v,t])=>'<button class="rt-option" data-divider="'+v+'">'+t+'</button>').join(''));if(anchor)fitMenu(menu,anchor,true);menu.onclick=e=>{const type=e.target.closest('[data-divider]')?.dataset.divider;if(!type)return;if(!restore())return;const hr=existing||document.createElement('hr');hr.dataset.divider=type;hr.style.border='0';hr.style.borderTop=(type==='thick'?'3px':type==='double'?'4px':'1px')+' '+(type==='thick'?'solid':type)+' #c9c9c9';hr.style.margin='12px 0';if(!existing){const block=textBlock();block.after(hr);ensureTail(hr);}finish(hr.nextElementSibling||hr);};}
