window.addEventListener('keydown',e=>{const b=e.target.closest?.('.ibody');if(!enabled(b)||e.isComposing)return;body=b;const sel=getSelection();if(e.key==='Delete'&&selectedBlocks.size){e.preventDefault();e.stopImmediatePropagation();stateOf(b);selectedBlocks.forEach(n=>n.remove());selectedBlocks.clear();markSelection();if(!b.firstElementChild)b.append(plainParagraph(''));finish(b.lastElementChild);return;}if(e.key!=='Backspace'||!sel.isCollapsed||!sel.rangeCount)return;const p=nodeOf(sel.anchorNode).closest('p');if(!p||!b.contains(p))return;const before=document.createRange();before.selectNodeContents(p);before.setEnd(sel.anchorNode,sel.anchorOffset);if(before.toString())return;const prev=p.previousElementSibling;if(prev?.matches('hr')){e.preventDefault();e.stopImmediatePropagation();selectedBlocks.clear();selectedBlocks.add(prev);markSelection();return;}if(prev?.matches('p')&&!p.textContent.trim()){e.preventDefault();e.stopImmediatePropagation();stateOf(b);p.remove();finish(prev);}},true);
let marquee=null;
window.addEventListener('pointerdown',e=>{const b=e.target.closest?.('.ibody');if(!enabled(b)||e.button!==0||e.target!==b)return;body=b;selectedBlocks.clear();markSelection();marquee={x:e.clientX,y:e.clientY,b,el:null};},true);
window.addEventListener('pointermove',e=>{if(!marquee)return;const m=marquee;if(!m.el&&Math.hypot(e.clientX-m.x,e.clientY-m.y)<5)return;if(!m.el){m.el=document.createElement('div');m.el.className='rt-marquee';document.body.append(m.el);}const left=Math.min(m.x,e.clientX),top=Math.min(m.y,e.clientY),right=Math.max(m.x,e.clientX),bottom=Math.max(m.y,e.clientY);m.el.style.cssText='left:'+left+'px;top:'+top+'px;width:'+(right-left)+'px;height:'+(bottom-top)+'px';selectedBlocks.clear();for(const n of m.b.children){const r=n.getBoundingClientRect();if(r.bottom>top&&r.top<bottom&&r.right>left&&r.left<right)selectedBlocks.add(n);}getSelection().removeAllRanges();markSelection();e.preventDefault();},true);
window.addEventListener('pointerup',()=>{if(!marquee)return;const m=marquee;marquee=null;if(m.el){m.el.remove();m.b.focus({preventScroll:true});skipBlockClickUntil=Date.now()+800;}},true);
document.addEventListener('mouseup',e=>{const b=e.target.closest?.('.ibody');if(!enabled(b)||marquee)return;const sel=getSelection();if(sel.isCollapsed||!sel.rangeCount)return;const r=sel.getRangeAt(0),a=nodeOf(r.startContainer),z=nodeOf(r.endContainer);if(a.closest('table')||z.closest('table'))return;const nearest=n=>{while(n&&n.parentElement!==b)n=n.parentElement;return n;};const first=nearest(a),last=nearest(z);if(first&&last&&first!==last){selectedBlocks.clear();let n=first;while(n){selectedBlocks.add(n);if(n===last)break;n=n.nextElementSibling;}markSelection();}},true);

