let tableCorner=null;
window.addEventListener('mousedown',e=>{const w=e.target.closest?.('.rt-table-wrap'),b=w?.closest('.ibody');if(!enabled(b)||e.button!==0)return;const r=w.getBoundingClientRect();if(e.clientX<r.right-16||e.clientY<r.bottom-16)return;e.preventDefault();e.stopImmediatePropagation();body=b;stateOf(b);hide();const table=w.querySelector('table');tableCorner={table,x:e.clientX,y:e.clientY,w:table.offsetWidth,h:table.offsetHeight};},true);
