async function insertCellPhotos(cell,files,range){const b=cell.closest('.ibody');if(!enabled(b))return;body=b;stateOf(b);for(const file of files){if(!/^image\/(png|jpeg|webp|gif|bmp)$/i.test(file.type))continue;try{const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});if(!enabled(b)||!cell.isConnected)return;const img=document.createElement('img');img.src=data;img.alt=file.name||'사진';img.style.width='100%';img.style.maxWidth='100%';img.style.height='auto';await img.decode();if(range&&cell.contains(range.commonAncestorContainer)){range.deleteContents();range.insertNode(img);range.setStartAfter(img);range.collapse(true);}else cell.append(img);const br=document.createElement('br');img.after(br);const caret=document.createRange();caret.setStartAfter(br);caret.collapse(true);getSelection().removeAllRanges();getSelection().addRange(caret);saved=caret.cloneRange();body=b;dirty();}catch{toast('사진을 불러오지 못했습니다. 이미지 파일을 확인해 주세요.');}}}
function pickCellPhoto(cell){const range=saved?.cloneRange();closeFly();const input=document.createElement('input');input.type='file';input.className='pop';input.addEventListener('click',e=>e.stopPropagation());input.accept='image/png,image/jpeg,image/webp,image/gif,image/bmp';input.multiple=true;input.onchange=()=>{insertCellPhotos(cell,[...input.files],range);input.remove();};input.oncancel=()=>input.remove();input.style.display='none';document.body.append(input);input.click();}
window.addEventListener('paste',e=>{const b=e.target.closest?.('.ibody'),sel=getSelection(),cell=sel.rangeCount?nodeOf(sel.anchorNode).closest('td,th'):null;const files=[...(e.clipboardData?.files||[])].filter(f=>f.type.startsWith('image/'));if(!enabled(b)||!cell||!files.length)return;e.preventDefault();e.stopImmediatePropagation();insertCellPhotos(cell,files,sel.getRangeAt(0).cloneRange());},true);
window.addEventListener('dragover',e=>{const cell=e.target.closest?.('td,th');if(cell&&enabled(cell.closest('.ibody'))&&[...(e.dataTransfer?.types||[])].includes('Files')){e.preventDefault();e.stopImmediatePropagation();e.dataTransfer.dropEffect='copy';}},true);
window.addEventListener('drop',e=>{const cell=e.target.closest?.('td,th');const files=[...(e.dataTransfer?.files||[])].filter(f=>f.type.startsWith('image/'));if(!cell||!enabled(cell.closest('.ibody'))||!files.length)return;e.preventDefault();e.stopImmediatePropagation();insertCellPhotos(cell,files,null);},true);
